package com.moinmalik.routine;
import android.app.*; import android.content.*; import android.media.RingtoneManager; import android.net.Uri; import android.os.Build; import androidx.core.app.NotificationCompat; import org.json.*;
public class RoutineAlarmReceiver extends BroadcastReceiver { public void onReceive(Context c,Intent intent){ try{ int id=intent.getIntExtra("id",0); String raw=c.getSharedPreferences(AlarmScheduler.PREF,0).getString(String.valueOf(id),null); if(raw==null)return; JSONObject s=new JSONObject(raw); String channel=s.optString("mode","notification").equals("full")?"routine_alarms":"routine_reminders"; NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE); if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(channel,channel.equals("routine_alarms")?"Routine alarms":"Routine reminders",channel.equals("routine_alarms")?NotificationManager.IMPORTANCE_HIGH:NotificationManager.IMPORTANCE_DEFAULT)); Intent screen=new Intent(c,AlarmActivity.class).putExtra("spec",raw).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP); PendingIntent open=PendingIntent.getActivity(c,id,screen,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE); Uri sound=s.optString("sound").equals("silent-vibration")?null:RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM); NotificationCompat.Builder b=new NotificationCompat.Builder(c,channel).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(s.optString("label","Routine alarm")).setContentText("Scheduled routine reminder").setAutoCancel(true).setContentIntent(open).setPriority(NotificationCompat.PRIORITY_MAX).setSound(sound).setVibrate(s.optBoolean("vibration",true)?new long[]{0,500,500}:null); if(s.optString("mode").equals("full"))b.setFullScreenIntent(open,true).setOngoing(true); nm.notify(id,b.build()); c.getSharedPreferences(AlarmScheduler.PREF,0).edit().remove(String.valueOf(id)).apply(); }catch(Exception ignored){} } }
